import{_ as e,o as r,c as i,a3 as o}from"./chunks/framework.BYhc_8eO.js";const p=JSON.parse('{"title":"Programando","description":"Usando Scratch para construir programas","frontmatter":{"title":"Programando","description":"Usando Scratch para construir programas","weight":20,"draft":false,"icon":"fas fa-puzzle-piece"},"headers":[],"relativePath":"scratch/entorno-scratch/index.md","filePath":"04_Scratch/03_Programando_Scratch/index.md"}'),t={name:"scratch/entorno-scratch/index.md"};function c(n,a,s,d,l,u){return r(),i("div",null,[...a[0]||(a[0]=[o('<div class="hugo-objetivos"><div class="hugo-objetivos-title"><i class="fas fa-check-circle" aria-hidden="true"></i> Objetivos</div><div class="hugo-objetivos-sub">Qué veremos aquí</div><ul><li>Realizando programas con Scratch</li><li>La Instalación o uso del entorno de ejecución</li><li>Analizando el entorno de ejecución</li></ul></div><h1 id="usando-scratch" tabindex="-1">Usando Scratch <a class="header-anchor" href="#usando-scratch" aria-label="Permalink to &quot;Usando Scratch&quot;">​</a></h1><div class="iframe-container"><iframe src="https://es.wikieducator.org/index.php?oldid=28608" width="100%" height="1900">WikiEducator </iframe></div><h1 id="instalacion" tabindex="-1">Instalación <a class="header-anchor" href="#instalacion" aria-label="Permalink to &quot;Instalación&quot;">​</a></h1><p>Scratch no hace falta instalarlo, ya que se puede usar directamente desde el navegador. Para ello, hay que acceder a la página web de Scratch y crear una cuenta de usuario. Una vez creada la cuenta, se puede empezar a programar directamente desde el navegador.</p><div class="iframe-container"><iframe src="https://es.wikieducator.org/index.php?curid=6643" width="100%" height="2911">WikiEducator </iframe></div><h1 id="entorno-de-ejecucion" tabindex="-1">Entorno de ejecución <a class="header-anchor" href="#entorno-de-ejecucion" aria-label="Permalink to &quot;Entorno de ejecución&quot;">​</a></h1><p>Es complicado al principio localizar los elementos del entorno de ejecución, pero con un poco de práctica se puede llegar a dominarlo.</p><p>Veremos cómo las insstrucciones se agrupan en bloques y cómo se pueden arrastrar y soltar para formar un programa. Además, aprenderemos a utilizar los diferentes tipos de bloques y cómo interactúan entre sí.</p><div class="iframe-container"><iframe src="https://es.wikieducator.org/index.php?oldid=28608" width="100%" height="1900">WikiEducator </iframe></div>',10)])])}const m=e(t,[["render",c]]);export{p as __pageData,m as default};
